update public.learning_paths
set
  title = 'Vector Graphics (Illustrator)',
  goal = 'Vector Graphics (Illustrator)',
  summary = 'Students understand vector graphics as scalable, editable systems for identity, illustration, icons, diagrams, packaging, and digital products, and set up Illustrator files with measurement, alignment, artboard, and grid discipline. They build clean forms and Bezier paths, use appearance and color systems, integrate type, and design icons, logos, illustrations, patterns, and modular systems, then cover cross-app handoff, print and SVG output, critique and inclusive symbols, and a polished vector capstone.',
  data = $vectjson${"slug": "vector-graphics-illustrator", "title": "Vector Graphics (Illustrator)", "description": "Students understand vector graphics as scalable, editable systems for identity, illustration, icons, diagrams, packaging, and digital products, and set up Illustrator files with measurement, alignment, artboard, and grid discipline. They build clean forms and Bezier paths, use appearance and color systems, integrate type, and design icons, logos, illustrations, patterns, and modular systems, then cover cross-app handoff, print and SVG output, critique and inclusive symbols, and a polished vector capstone.", "topics": [{"id": "bebbaf6c-bddd-470b-a3df-7423b371839b", "type": "topic", "title": "Vector Graphics Foundations and Illustrator Workspace", "description": "Understand vector graphics as scalable, editable systems for identity, illustration, icons, diagrams, packaging, and digital products.", "children": [{"id": "eb87abc9-c175-41b7-aaea-21b622d8712b", "type": "subtopic", "title": "Vector versus raster logic", "children": [{"id": "a40f0b03-afbf-4e76-a448-cf0285205367", "type": "concept", "title": "Points, paths, curves, fills, strokes, shapes, groups, symbols, and outlines"}, {"id": "b1604a3b-77bd-4a00-a02b-86dac4662894", "type": "concept", "title": "Scalability, editability, file size, resolution independence, and output flexibility"}, {"id": "f7b42c72-903a-4f91-85cf-5a81a4be5ba6", "type": "concept", "title": "When to use Illustrator, Photoshop, InDesign, Figma, or a motion/web tool"}], "description": "Students begin by understanding why vector graphics behave differently from pixel-based images."}, {"id": "72e6726a-3cfb-4de6-b03f-ff070d46f38d", "type": "subtopic", "title": "Illustrator interface fluency", "children": [{"id": "6b9862c2-ef3e-42d4-8525-73529320ab5a", "type": "concept", "title": "Tools panel, control bar, properties, layers, appearance, swatches, libraries, pathfinder, align, and transform panels"}, {"id": "93dabdab-569a-41cf-92b5-769f1275d314", "type": "concept", "title": "Selection tool, direct selection tool, isolation mode, preview modes, outline mode, and zoom/navigation habits"}, {"id": "f49637e7-2d6a-48db-b071-01306b189763", "type": "concept", "title": "Custom workspaces, keyboard shortcuts, tool presets, and efficient panel setups"}], "description": "Workspace fluency lets students spend attention on form and communication instead of hunting for tools."}, {"id": "dbe2566c-5b6b-43e7-98a7-c72d9b267894", "type": "subtopic", "title": "Professional vector habits", "children": [{"id": "26d4c775-a44c-49d5-889a-46ed5a1f307f", "type": "concept", "title": "Naming layers, grouping intentionally, locking references, saving versions, and preserving editable files"}, {"id": "9a0129c0-d204-465e-a38b-88686f143a5f", "type": "concept", "title": "Using artboards, guides, grids, global colors, styles, symbols, and libraries"}, {"id": "fb760f98-7d57-4959-8cea-2bb0526d4f7c", "type": "concept", "title": "Common beginner errors: messy paths, excessive points, expanded effects too early, and unnamed assets"}], "description": "Strong vector work depends on clean construction, organization, and production discipline."}]}, {"id": "0419b5bb-1540-4f31-8597-bbceb49f6e39", "type": "topic", "title": "Documents, Artboards, Grids, Guides, and Precision Workflow", "description": "Set up Illustrator files with the measurement, alignment, artboard, and grid discipline expected in professional design work.", "children": [{"id": "44726da9-3cde-49c7-985a-84c232110d2c", "type": "subtopic", "title": "Document setup", "children": [{"id": "47ff4e9f-4171-4a7b-b73c-4a8533c90a0e", "type": "concept", "title": "Units, artboards, bleed, color mode, raster effects settings, document profiles, and templates"}, {"id": "4d98b896-91dd-4350-b4d9-dd9a153c9e42", "type": "concept", "title": "Multiple artboards for campaigns, identity systems, icon sets, and responsive exports"}, {"id": "cfb3790a-f182-49eb-8d95-530aa020341a", "type": "concept", "title": "File naming, versioning, linked assets, and folder structure"}], "description": "Correct setup prevents downstream problems in print, web, packaging, and portfolio exports."}, {"id": "f896112f-c305-46af-85bb-19d25cc82419", "type": "subtopic", "title": "Grids and alignment", "children": [{"id": "8d648715-a387-4484-92de-39bab92e0c15", "type": "concept", "title": "Rulers, guides, smart guides, grids, snap settings, align, distribute, transform, and measurement tools"}, {"id": "084eaca4-e825-4d44-aa58-6e9969e73560", "type": "concept", "title": "Baseline grids, modular grids, logo grids, icon grids, and construction diagrams"}, {"id": "d0af09cf-c9d1-4ea6-b6f1-3d3f87593e8e", "type": "concept", "title": "Optical alignment versus mathematical alignment"}], "description": "Precision is not stiffness; it is how complex designs stay coherent."}, {"id": "79f8804b-f016-4aa5-b7ed-8c1d413478e2", "type": "subtopic", "title": "Artboard systems", "children": [{"id": "d2192797-790b-4916-9c79-1efadf760256", "type": "concept", "title": "Artboard naming, export ranges, template artboards, safe areas, and presentation boards"}, {"id": "f71d2aa8-1d35-4888-bc26-e6cacf096969", "type": "concept", "title": "Designing for poster, social, web, icon, packaging, and brand application sizes"}, {"id": "ed1906ea-8e37-4834-a02f-31b5ae4cf5df", "type": "concept", "title": "Keeping working areas separate from final deliverable areas"}], "description": "Students learn to manage multiple related outputs inside one production file."}]}, {"id": "f5d8c443-a8a6-449e-8496-98d19550f0a1", "type": "topic", "title": "Shape Construction, Pathfinder, Shape Builder, and Geometry", "description": "Build clean vector forms from simple shapes using additive, subtractive, and modular construction methods.", "children": [{"id": "aba0f83b-8a4f-496b-acf1-3402789f2e6a", "type": "subtopic", "title": "Geometric construction", "children": [{"id": "b3c9a07e-70c5-4b76-97a7-395535c95ed5", "type": "concept", "title": "Rectangles, ellipses, polygons, stars, line segments, arcs, spirals, and custom shapes"}, {"id": "465f6153-3fce-4b95-bb23-1d8d7b91c784", "type": "concept", "title": "Rotation, scaling, reflection, shearing, duplication, and transform again"}, {"id": "9f65b7aa-5c3f-42b7-8eb2-f1105c5d6234", "type": "concept", "title": "Symmetry, proportion, negative space, and figure-ground relationships"}], "description": "Clean vector forms often begin as simple shapes combined with disciplined logic."}, {"id": "f2cc6682-98f2-4383-944d-d86463917574", "type": "subtopic", "title": "Pathfinder and Shape Builder", "children": [{"id": "a46c5640-ceb1-4542-8882-7f1a129189b6", "type": "concept", "title": "Unite, minus front, intersect, exclude, divide, trim, merge, crop, outline, and minus back"}, {"id": "2918a33e-eed7-4688-8ed4-3421e374b6b0", "type": "concept", "title": "Shape Builder adding/subtracting, live shapes, compound paths, and compound shapes"}, {"id": "b7d0bbd9-5413-4aac-9369-6cee48a98aeb", "type": "concept", "title": "Choosing editable construction versus final cleaned geometry"}], "description": "Boolean operations help students construct marks, icons, and illustrations without messy manual drawing."}, {"id": "b05eb0f2-5383-4fba-9033-69b37b80ae9c", "type": "subtopic", "title": "Form refinement", "children": [{"id": "bd06db42-9ea3-4ea4-b2cd-421e36beba0f", "type": "concept", "title": "Corner radius, simplify path, offset path, width tool, smooth tool, join, average, and outline stroke"}, {"id": "22b97e1f-9af4-49fc-93c1-8cea231aff03", "type": "concept", "title": "Removing stray points, closing gaps, correcting overlaps, and checking silhouette quality"}, {"id": "cef52dd6-0110-43cb-8f9c-60325f339d9b", "type": "concept", "title": "Optical correction for curves, intersections, spacing, and small-size reproduction"}], "description": "Students learn to simplify, balance, and polish vector shapes so they feel intentional."}]}, {"id": "35373a84-8cc0-4534-af22-add562034622", "type": "topic", "title": "Pen Tool, Bezier Curves, Paths, and Anchor Editing", "description": "Gain control over curves, handles, points, and path quality so drawings are intentional rather than accidental.", "children": [{"id": "93966f4f-5a5b-45e6-9fb9-d2ebc5cf768d", "type": "subtopic", "title": "Pen tool fundamentals", "children": [{"id": "454fed2c-89cf-46ee-847b-2869c3219393", "type": "concept", "title": "Straight points, smooth points, corner points, handles, direction lines, and path closure"}, {"id": "30e0f06d-85d0-4e34-8fb9-9d38b2206446", "type": "concept", "title": "Clicking, dragging, converting points, adding points, deleting points, and continuing paths"}, {"id": "2ccf19a1-c6fe-4db0-923a-2641264263e4", "type": "concept", "title": "Drawing with fewer points for cleaner curves"}], "description": "The pen tool is where students gain exact control over line, curve, and contour."}, {"id": "7344ffc2-e1f1-4f98-8391-d7c01cd1aba4", "type": "subtopic", "title": "Bezier curve quality", "children": [{"id": "9633e824-e90a-4e82-a297-143e04492b72", "type": "concept", "title": "Tangent continuity, handle length, handle angle, extrema placement, and curve economy"}, {"id": "1a4bb46b-2a59-4659-b417-73f4320a1941", "type": "concept", "title": "Avoiding lumpy curves, broken handles, excess anchors, and accidental flat spots"}, {"id": "565efe5e-d620-4646-aec7-91a90653521d", "type": "concept", "title": "Tracing references with interpretation rather than mechanical copying"}], "description": "Good curves look smooth because the points and handles are placed with intent."}, {"id": "ba42a263-deed-4dcd-8073-68e5f934d1c0", "type": "subtopic", "title": "Path editing and cleanup", "children": [{"id": "13062578-9d18-4ce6-8e5e-8a4019b45cf0", "type": "concept", "title": "Direct selection, anchor point tool, join, average, outline mode, simplify, smooth, and path direction"}, {"id": "01991d2b-b2da-42db-92be-c66cd636a508", "type": "concept", "title": "Open paths, overlapping paths, compound paths, clipping paths, and stray points"}, {"id": "8f565a0d-a8e2-4c36-b943-b884d1ef230f", "type": "concept", "title": "Preparing paths for logos, icons, cutting, engraving, animation, and SVG export"}], "description": "Students learn to diagnose path problems and prepare artwork for production."}]}, {"id": "df1d54b6-eec4-4d03-960f-be77ed005786", "type": "topic", "title": "Stroke, Fill, Appearance Panel, Graphic Styles, and Effects", "description": "Use Illustrator's appearance model to create editable visual systems with strokes, fills, effects, and reusable styles.", "children": [{"id": "dcdbaf96-45a6-449b-afb4-1b4f068d2962", "type": "subtopic", "title": "Stroke and fill systems", "children": [{"id": "ecc094de-d1c6-4890-99cc-28d0f93cbf26", "type": "concept", "title": "Stroke weight, cap, corner, dashed line, arrowheads, variable width, brush strokes, and fills"}, {"id": "25cbc29f-33d5-48dc-baff-01343104710b", "type": "concept", "title": "Stacking multiple strokes and fills on one object"}, {"id": "3cd9c188-ef6b-447b-82e5-758a7747d02c", "type": "concept", "title": "Expanding appearance only when production requires it"}], "description": "Stroke and fill settings are core building blocks of visual style."}, {"id": "2478e112-69d0-4b5f-a60e-5ea0c81a5798", "type": "subtopic", "title": "Appearance panel logic", "children": [{"id": "c611ba7d-26a7-4eb2-8f15-1900f4feb123", "type": "concept", "title": "Multiple fills, multiple strokes, effects order, opacity, blend modes, and targeted appearance attributes"}, {"id": "91450a3a-60f5-49ec-8e66-5ca0a826b6ba", "type": "concept", "title": "Graphic styles, reusable treatments, and consistent design systems"}, {"id": "f308d25e-72ff-4f50-a99f-a1861777d95d", "type": "concept", "title": "Editing object appearance versus group, layer, and character appearance"}], "description": "The appearance panel lets students keep effects editable and reusable."}, {"id": "02f099b5-2bef-4258-8663-982b2dd1fc78", "type": "subtopic", "title": "Effects and brushes", "children": [{"id": "2bec89be-7531-47fb-9137-80faa594a4eb", "type": "concept", "title": "Offset path, transform effect, roughen, distort, blur, drop shadow, 3D/materials overview, and warp"}, {"id": "e9520ea7-1653-48a7-ad13-866e8c004b2d", "type": "concept", "title": "Art brushes, pattern brushes, scatter brushes, calligraphic brushes, and width profiles"}, {"id": "9800de38-05b7-4a4a-a87c-6dc901e24f09", "type": "concept", "title": "Balancing editable effects with output reliability"}], "description": "Effects should support a concept, not just decorate an object."}]}, {"id": "b6aeee29-6b01-406e-9e2d-9de9c2dde732", "type": "topic", "title": "Color Systems, Swatches, Gradients, Patterns, and Recoloring", "description": "Develop production-aware color systems for screen, print, identity, illustration, and multi-asset design work.", "children": [{"id": "3c6d76a9-7cd8-4088-92f6-b91da5fdbabe", "type": "subtopic", "title": "Swatches and color modes", "children": [{"id": "9b066135-af7e-4f4b-ae6d-879ae76c2971", "type": "concept", "title": "RGB, CMYK, spot color, Pantone, process color, global color, tint, and registration color"}, {"id": "13f14091-5b9c-4554-b70f-e87c1c4d6ad8", "type": "concept", "title": "Document color mode, color profiles, gamut, and screen versus print expectations"}, {"id": "0b5fdfe2-f610-4ad5-b81c-e884ac70cb23", "type": "concept", "title": "Naming swatches and maintaining color consistency across assets"}], "description": "Production color starts with organized swatches and a clear understanding of output context."}, {"id": "6a3d0d2c-e245-451c-9f40-13fff350a95e", "type": "subtopic", "title": "Gradients and blends", "children": [{"id": "2de1d8dd-1b5b-4693-839a-3278856a7db1", "type": "concept", "title": "Linear, radial, freeform gradients, gradient mesh overview, blends, opacity, and transparency"}, {"id": "220bb9a1-a8d0-45f0-96c1-58dc18fa23bc", "type": "concept", "title": "Color transitions, lighting effects, dimensional marks, and background systems"}, {"id": "d8c7cb3c-8dd8-4a63-9d9e-4e42bfc51e24", "type": "concept", "title": "Avoiding banding, muddy gradients, and unprintable transparency surprises"}], "description": "Gradients and blends can create depth, rhythm, and smooth transitions when used with restraint."}, {"id": "e942fb07-714b-463c-92af-0842c6f19ea3", "type": "subtopic", "title": "Patterns and recoloring", "children": [{"id": "1ec813e6-f0e4-481f-875c-8b2fbc4fbe65", "type": "concept", "title": "Pattern options, repeat types, tile edges, motif spacing, and pattern swatches"}, {"id": "6eb9cbcb-72c8-4310-a067-d76fa668c34e", "type": "concept", "title": "Recolor Artwork, color groups, harmony rules, randomization, and palette variants"}, {"id": "f4c1f066-4b50-4cb0-954a-d0271b5ff110", "type": "concept", "title": "Accessibility, contrast, brand consistency, and cultural meaning of color"}], "description": "Recoloring tools let students test palette systems and build flexible design families."}]}, {"id": "5296f45e-9e1f-4d21-ab37-ffddd1488921", "type": "topic", "title": "Typography, Letterforms, and Type-Based Vector Design", "description": "Integrate type, lettering, hierarchy, and letterform customization into vector compositions and identity systems.", "children": [{"id": "f6526bd0-68cc-40d0-a987-621b3b260e45", "type": "subtopic", "title": "Type in Illustrator", "children": [{"id": "9ddca52d-2eb8-41b4-bd10-f351a2ff561e", "type": "concept", "title": "Point type, area type, type on a path, vertical type, character panel, paragraph panel, tabs, and OpenType features"}, {"id": "7f3ce324-681e-4cec-a31e-0c70579ee0df", "type": "concept", "title": "Kerning, tracking, leading, alignment, hierarchy, and typographic voice"}, {"id": "1ef6c448-98d5-4787-a7fe-1251ccd0d2dc", "type": "concept", "title": "When to keep type live and when to outline it for production"}], "description": "Students learn how Illustrator handles type for logos, posters, icons, and short-form graphics."}, {"id": "71263440-986c-4576-bcf3-9b80f42fe694", "type": "subtopic", "title": "Letterform customization", "children": [{"id": "388550ef-2148-4c76-820d-926cbb04e2cf", "type": "concept", "title": "Anatomy, counters, stems, terminals, bowls, x-height, baseline, cap height, overshoot, and contrast"}, {"id": "66245171-411d-4799-b479-ac26e86f7c3d", "type": "concept", "title": "Custom logotypes, monograms, ligatures, wordmarks, and display lettering"}, {"id": "5978d07d-ed02-4c8b-b9a8-d5b6195f0073", "type": "concept", "title": "Maintaining readability while modifying letterforms"}], "description": "Vector type work becomes powerful when students understand the form of letters."}, {"id": "8a2759bc-a230-45d4-8c3a-ce224e51d14e", "type": "subtopic", "title": "Type-image integration", "children": [{"id": "d1ad4f1c-3716-46c6-9d36-a258d7bca87f", "type": "concept", "title": "Lockups, badges, labels, posters, social graphics, packaging panels, and editorial illustrations"}, {"id": "fd8fb69a-fa87-4bec-9e33-fc2211c1b278", "type": "concept", "title": "Hierarchy between text, mark, image, and supporting information"}, {"id": "7177388a-273e-481b-b930-ca7c0b3c89ad", "type": "concept", "title": "Exporting type safely for print, SVG, PDF, and collaborative files"}], "description": "Typography in Illustrator often needs to work with symbols, images, patterns, and identity systems."}]}, {"id": "2780b591-1ec7-4c79-84bf-ca8f05f43762", "type": "topic", "title": "Icons, Symbols, Pictograms, and Visual Language Systems", "description": "Design coherent icon and symbol systems that communicate clearly at multiple sizes and in multiple contexts.", "children": [{"id": "939b0f29-9f88-47ec-ad85-bac7f16ce9df", "type": "subtopic", "title": "Icon principles", "children": [{"id": "0100957c-0bc0-4ee6-8c1d-9727e4d59624", "type": "concept", "title": "Metaphor, convention, recognition, simplification, silhouette, scale, and context"}, {"id": "f8920eb1-f1c7-47d0-b213-c9f63ccf0d4d", "type": "concept", "title": "Pixel grid versus vector grid, stroke icons, filled icons, duotone icons, and responsive icon variants"}, {"id": "9f8c5361-758e-44df-bf6d-28b6aa4ce2e7", "type": "concept", "title": "Testing icons at small sizes and in real interfaces"}], "description": "Icon design teaches students to communicate a concept with minimal, structured form."}, {"id": "9404e40c-7759-4602-ad6b-c39cc1cdf3ca", "type": "subtopic", "title": "System consistency", "children": [{"id": "9d12bf5c-cf9b-44e5-a7bf-97ab65606592", "type": "concept", "title": "Grid, stroke weight, corner radius, optical size, visual weight, perspective, detail level, and negative space"}, {"id": "5eaacb99-275b-4356-9292-ffa30ea2d699", "type": "concept", "title": "Symbol libraries, components, variants, naming, and export sets"}, {"id": "1147cc93-6e5f-4866-a4f5-9c805b07902d", "type": "concept", "title": "Accessibility, labels, ambiguity, and culturally specific symbols"}], "description": "A good icon set feels like a family, not a collection of unrelated drawings."}, {"id": "5768f1c2-f0d7-465c-b487-d24d67baf862", "type": "subtopic", "title": "Pictograms and wayfinding", "children": [{"id": "42349d60-6ae9-493f-870a-85761195265f", "type": "concept", "title": "Universal symbols, wayfinding, safety icons, instructional diagrams, and public information graphics"}, {"id": "05b72919-b887-47e2-84ec-e9362e63ba1a", "type": "concept", "title": "Legibility at distance, contrast, figure-ground, and environment"}, {"id": "728855e8-afec-4e71-ae75-faa861285273", "type": "concept", "title": "Inclusive representation and avoiding stereotypes"}], "description": "Symbols become public communication tools when used in signage, maps, instructions, and systems."}]}, {"id": "4678c041-e7af-47a6-89a4-aed7c0513925", "type": "topic", "title": "Logo Marks, Identity Systems, and Brand Applications", "description": "Apply vector craft to marks, lockups, brand assets, usage rules, and real-world applications.", "children": [{"id": "cbbe96b2-3244-4765-8219-3a1dd01632bd", "type": "subtopic", "title": "Logo construction", "children": [{"id": "7dd1ff0c-64ed-41da-84a3-f5afe09b9a20", "type": "concept", "title": "Wordmarks, lettermarks, pictorial marks, abstract marks, combination marks, badges, and seals"}, {"id": "51cc9606-3ffe-419a-8580-cefa96c9a6dd", "type": "concept", "title": "Proportion, geometry, optical correction, negative space, and small-size testing"}, {"id": "4e7bf545-f351-4f62-bf53-65fbf4dfeff9", "type": "concept", "title": "Black-and-white tests, reverse tests, one-color tests, and favicon/social avatar tests"}], "description": "Logo design asks for simple, memorable, reproducible vector form."}, {"id": "0e294f13-86f1-44c5-8925-5f1204926484", "type": "subtopic", "title": "Identity systems", "children": [{"id": "23f170f4-e00d-4b93-8043-ad0e0bca1338", "type": "concept", "title": "Primary and secondary marks, lockups, clear space, minimum size, color variants, typography, and graphic elements"}, {"id": "4cc5d35e-fcd1-4da3-adda-40d3a0d84720", "type": "concept", "title": "Brand pattern, icon set, illustration style, social templates, signage, packaging, and stationery"}, {"id": "9ddfd01b-6e52-4bf5-9826-64588d5a6d89", "type": "concept", "title": "Usage rules, misuse examples, and brand guideline basics"}], "description": "A mark becomes useful when it lives in a coherent system."}, {"id": "b44083f3-fcc0-4b47-9d96-2986a224a483", "type": "subtopic", "title": "Case-study thinking", "children": [{"id": "aa832b96-bf14-4810-b2fc-2c55f0c88b9f", "type": "concept", "title": "Research, naming, competitor audit, mood boards, sketches, digital exploration, refinement, and rationale"}, {"id": "99edcf51-4292-44e9-8736-8dc263559e74", "type": "concept", "title": "Presenting options, receiving critique, selecting directions, and revising marks"}, {"id": "fce42ee9-e660-4721-aa29-19af1c27a521", "type": "concept", "title": "Mockups, applications, and portfolio-ready process documentation"}], "description": "Students learn to explain logo decisions through strategy, audience, context, and craft."}]}, {"id": "5ead6510-325a-4e2c-9698-310f20a79bf8", "type": "topic", "title": "Vector Illustration, Stylization, Image Trace, and Digital Drawing", "description": "Create expressive vector illustrations while understanding style, simplification, reference, and trace limitations.", "children": [{"id": "bd6ebac7-0574-431c-8c85-cda5d1b1aa1c", "type": "subtopic", "title": "Vector illustration styles", "children": [{"id": "7d4d7ae6-a14a-42fd-a5aa-6ca5fffb69d8", "type": "concept", "title": "Flat illustration, line art, isometric illustration, editorial illustration, poster illustration, maps, and diagrams"}, {"id": "155dfe5a-5d57-4227-a6fe-7494950062ff", "type": "concept", "title": "Shape language, simplification, stylization, proportion, rhythm, and visual voice"}, {"id": "3683b667-66a0-4aba-97ed-76861d00c25a", "type": "concept", "title": "Reference use, sketch-to-vector workflow, and avoiding over-tracing"}], "description": "Vector illustration can be geometric, expressive, flat, dimensional, editorial, technical, or character-based."}, {"id": "63fbc95a-a9c3-4fbd-a782-4f827e31d107", "type": "subtopic", "title": "Digital drawing tools", "children": [{"id": "b3e40924-24e1-4633-b3fb-aa019c85a0ad", "type": "concept", "title": "Pencil, brush, blob brush, curvature tool, width tool, eraser, shaper, and touch tools"}, {"id": "0fdf6317-a2f7-4a23-b3f6-473e220d4ca8", "type": "concept", "title": "Tablet workflows, smoothing settings, pressure sensitivity, and brush libraries"}, {"id": "96e3fc58-6fbf-4378-8ee4-e6eead189b52", "type": "concept", "title": "Balancing hand-drawn energy with clean vector structure"}], "description": "Illustrator offers several drawing modes beyond the pen tool."}, {"id": "446742dd-1ef3-412e-a135-c8297448a560", "type": "subtopic", "title": "Image Trace and cleanup", "children": [{"id": "6bdbf65c-2089-4e64-85ab-70ab4a46bdc4", "type": "concept", "title": "Black-and-white trace, color trace, threshold, paths, corners, noise, expand, and igno